import java.sql.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.springframework.security.crypto.bcrypt.BCrypt;
/** Register only the Application Service's scoped correction identity. Never prints credentials. */
public class ProvisionApplicationCorrections {
 public static void main(String[] args)throws Exception{
  Path dir=Path.of(args[0]).toAbsolutePath();Properties runtime=new Properties(),application=new Properties();try(var r=Files.newBufferedReader(dir.resolve("runtime.properties"))){runtime.load(r);}Path file=dir.resolve("application.properties");try(var r=Files.newBufferedReader(file)){application.load(r);}String secret=application.getProperty("credflow.corrections.client-secret");
  try(var c=DriverManager.getConnection(runtime.getProperty("db.url"),runtime.getProperty("db.auth.user"),runtime.getProperty("db.auth.password"))){c.setAutoCommit(false);try(var s=c.createStatement();var r=s.executeQuery("SELECT USER,SYS_CONTEXT('USERENV','CON_NAME') FROM DUAL")){r.next();if(!"CF_AUTH".equals(r.getString(1))||!"FREEPDB1".equals(r.getString(2)))throw new IllegalStateException("Wrong database target");}
   boolean found;try(var s=c.prepareStatement("SELECT U.PASSWORD_HASH,U.USER_ROLE,C.SCOPES FROM CF_AUTH_SERVICE_CLIENTS C JOIN CF_AUTH_USERS U ON U.USER_ID=C.USER_ID WHERE C.CLIENT_ID='application-service'" );var r=s.executeQuery()){found=r.next();if(found&&(secret==null||!"APPLICATION_SERVICE".equals(r.getString(2))||!"workflow.revision".equals(r.getString(3))||!BCrypt.checkpw(secret,r.getString(1))))throw new IllegalStateException("Existing client does not match this private configuration; no credentials were reset");}
   if(!found){secret=UUID.randomUUID().toString()+UUID.randomUUID();String hash=BCrypt.hashpw(secret,BCrypt.gensalt(12));try(var s=c.prepareStatement("INSERT INTO CF_AUTH_USERS(PUBLIC_USER_ID,USERNAME,EMAIL_ADDRESS,PASSWORD_HASH,USER_ROLE,ACCOUNT_STATUS,CREATED_AT,UPDATED_AT) VALUES (?,'service.application','application@service.credflow.invalid',?,'APPLICATION_SERVICE','ACTIVE',SYSTIMESTAMP,SYSTIMESTAMP)")){s.setString(1,UUID.randomUUID().toString());s.setString(2,hash);s.executeUpdate();}try(var s=c.createStatement()){s.executeUpdate("INSERT INTO CF_AUTH_SERVICE_CLIENTS(USER_ID,CLIENT_ID,SCOPES) SELECT USER_ID,'application-service','workflow.revision' FROM CF_AUTH_USERS WHERE USERNAME='service.application'");}}
   // Persist local configuration before committing the new identity, so interrupted setup can retry safely.
   if(!Files.exists(dir.resolve("application.properties.before-corrections")))Files.copy(file,dir.resolve("application.properties.before-corrections"));String text=Files.readString(file,StandardCharsets.UTF_8);text=text.replaceAll("(?m)^credflow\\.corrections\\.[^\\r\\n]*\\R?","");text+="\ncredflow.corrections.enabled=true\ncredflow.corrections.client-id=application-service\ncredflow.corrections.client-secret="+secret+"\n";Files.writeString(file,text,StandardCharsets.UTF_8);c.commit();
  }System.out.println("Application correction identity and private runtime configuration are ready.");
 }
}
